 !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"20,2,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Fragile objects require strict force limits to avoid crushing or structural damage</span><span data-path-to-node=\"20,2,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"20,2,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. The design goal is to apply just enough grip force to securely hold the object without damaging it</span><span data-path-to-node=\"20,2,0,5\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"20,2,0,6\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li></ul>\r\n<img src=\"http://localhost:5001/uploads/b92da691-d328-488a-9fe4-03379e6518b4.png\" alt=\"Pasted image\">\r\n<div>\r\n<span data-path-to-node=\"18,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">A stable grasp requires balancing the downward gravitational force (<span class=\"math-inline\" data-math=\"W = mg\" data-index-in-node=\"68\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">W = mg</span>) with finger contact forces and friction to prevent slipping without crushing delicate items</span><span data-path-to-node=\"18,1\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"18,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">  </sources-carousel-inline>\r\n<br></div>',24,16,'https://www.youtube.com/watch?v=_7T1UWM69FA',NULL,'top','2026-10-21 12:31:47'),(7,1,1,'L15.6 — Static Equilibrium of the Arm','L15.6 — Static Equilibrium of the Arm','\r\n<p data-path-to-node=\"23\" id=\"p-rc_8e7fb282b1ba2638-249\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"23,0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">When a robotic arm holds a stationary load, all forces and moments acting throughout the mechanical structure must achieve complete equilibrium</span><span data-path-to-node=\"23,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"23,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p><ul data-path-to-node=\"24\" style=\"padding-inline-start: 32px;   margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"24,0,0\" id=\"p-rc_8e7fb282b1ba2638-250\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"24,0,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"24,0,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Force Balance</b>: For static equilibrium, the net vector sum of all external forces must equal zero (<span class=\"math-inline\" data-math=\"\\sum F = 0\" data-index-in-node=\"98\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">∑ F = 0</span>)</span><span data-path-to-node=\"24,0,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"24,0,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. This requires analyzing gravitational forces and finger contact forces across the object and arm segments independently</span><span data-path-to-node=\"24,0,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"24,0,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"24,1,0\" id=\"p-rc_8e7fb282b1ba2638-251\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"24,1,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"24,1,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Torque and Moments</b>: Torque is generated by force multiplied by the perpendicular lever arm distance (<span class=\"math-inline\" data-math=\"\\tau = r \\times F\" data-index-in-node=\"101\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">τ = r × F</span>)</span><span data-path-to-node=\"24,1,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"24,1,0,2\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Joint motors must supply sufficient torque to support both the weight of the arm segments and the external payload</span><span data-path-to-node=\"24,1,0,3\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"24,1,0,4\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">. Operating with a longer reach increases the effective moment arm, significantly increasing required joint torque</span><span data-path-to-node=\"24,1,0,5\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _nghost-ng-c46153305=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><sup _ngcontent-ng-c46153305=\"\" class=\"superscript\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important; font-size: 16px !important; background-color: transparent !important;\"></sup></source-footnote></response-element></span></span><span data-path-to-node=\"24,1,0,6\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">.</span><sources-carousel-inline ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c1750423854=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">   <source-inline-chip _ngcontent-ng-c1750423854=\"\" _nghost-ng-c2931205832=\"\" class=\"ng-star-inserted\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"></source-inline-chip></sources-carousel-inline></p></li><li style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><p data-path-to-node=\"24,2,0\" id=\"p-rc_8e7fb282b1ba2638-252\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span data-path-to-node=\"24,2,0,0\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><b data-path-to-node=\"24,2,0,0\" data-index-in-node=\"0\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\">Center of Mass</b>: Mass distribution directly affects structural balance</span><span data-path-to-node=\"24,2,0,1\" class=\"\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><span style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><response-element class=\"no-md\" ng-version=\"0.0.0-PLACEHOLDER\" style=\"margin-top: 0px !important; margin-left: 0px !important; margin-right: 0px !important;\"><source-footnote _ng